  3→import { createTestTextFile, cleanupTestFiles } from '../utils/test-files';
  4→import { FileListPage } from '../page-objects/file-browser/file-list.page';
  5→import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
  6→import { SearchPalettePage } from '../page-objects/dialogs/search-palette.page';
