  8→/**
  9→ * Search Workflow E2E Test Suite
 10→ *
 11→ * Tests the client-side search feature end-to-end:
 12→ * 1. Open search palette via Cmd/Ctrl+K keyboard shortcut
 13→ * 2. Open search palette via header button click
 14→ * 3. Type query and verify fuzzy-matched results appear
 15→ * 4. No-results state for nonsense queries
 16→ * 5. Select result and verify navigation to correct folder
 17→ * 6. Keyboard navigation with Enter to select
 18→ * 7. Escape closes palette
 19→ * 8. Click outside closes palette
 20→ *
 21→ * Uses a single login session with serial test execution.
 22→ * Uploads a uniquely named file for deterministic search results.
 23→ */
 24→test.describe.serial('Search Workflow', () => {
 25→  let browser: Browser;
 26→  let context: BrowserContext;
 27→  let page: Page;
 28→
 29→  // Page objects
 30→  let fileList: FileListPage;
 31→  let uploadZone: UploadZonePage;
 32→  let searchPalette: SearchPalettePage;
 33→
 34→  // Test data
 35→  const runId = Date.now();
 36→  const testFileName = `search-test-${runId}.txt`;
 37→
 38→  test.beforeAll(async ({ browser: testBrowser }) => {
 39→    browser = testBrowser;
 40→    context = await browser.newContext();
 41→    page = await context.newPage();
 42→
 43→    // Initialize page objects
 44→    fileList = new FileListPage(page);
 45→    uploadZone = new UploadZonePage(page);
 46→    searchPalette = new SearchPalettePage(page);
 47→  });
 48→
 49→  test.afterAll(async () => {
 50→    cleanupTestFiles();
 51→    if (context) {
 52→      await context.close();
 53→    }
 54→  });
 55→
 56→  // ============================================
 57→  // Setup
 58→  // ============================================
 59→
 60→  test('0.1 Login and create test content', async () => {
 61→    // Login
 62→    await loginViaEmail(page, TEST_CREDENTIALS.email);
 63→    await page.waitForURL('**/files', { timeout: 60000 });
 64→
 65→    // Create and upload a uniquely named text file
 66→    const testFile = createTestTextFile(testFileName, `Search test content ${runId}`);
 67→    await uploadZone.uploadFile(testFile.path);
 68→
 69→    // Wait for the file to appear in the file list
 70→    await fileList.waitForItemToAppear(testFileName, { timeout: 30000 });
 71→  });
 72→
 73→  // ============================================
 74→  // 1. Open / Close via shortcuts
 75→  // ============================================
 76→
 77→  test('1.1 Open search palette via Cmd+K', async () => {
 78→    // Press Meta+K to open search palette
 79→    await page.keyboard.press('Meta+k');
 80→    await searchPalette.waitForOpen({ timeout: 5000 });
 81→
 82→    // Verify input is focused
 83→    await expect(searchPalette.input()).toBeFocused();
 84→
 85→    // Close via Escape
 86→    await page.keyboard.press('Escape');
 87→    await searchPalette.waitForClosed({ timeout: 5000 });
 88→  });
 89→
 90→  test('1.2 Open search palette via header button', async () => {
 91→    // Click the header search button
 92→    await searchPalette.headerSearchButton().click();
 93→    await searchPalette.waitForOpen({ timeout: 5000 });
 94→
 95→    // Verify input is focused
 96→    await expect(searchPalette.input()).toBeFocused();
 97→
 98→    // Close via Escape for cleanup
 99→    await page.keyboard.press('Escape');
100→    await searchPalette.waitForClosed({ timeout: 5000 });
101→  });
102→
103→  // ============================================
104→  // 2. Search queries and results
105→  // ============================================
106→
107→  test('2.1 Type query and verify results appear', async () => {
108→    // Open palette
109→    await page.keyboard.press('Meta+k');
110→    await searchPalette.waitForOpen({ timeout: 5000 });
111→
112→    // Type the first part of the test file name (enough for a match)
113→    const queryText = `search-test-${runId}`;
114→    await searchPalette.typeQuery(queryText.slice(0, 12));
115→
116→    // Wait for results (index build + debounce may take time on first open)
117→    await searchPalette.waitForResults({ timeout: 15000 });
118→
119→    // Verify at least one result appears
120→    const resultCount = await searchPalette.getResultCount();
121→    expect(resultCount).toBeGreaterThan(0);
122→
123→    // Verify the test file is in the results
124→    const names = await searchPalette.getResultNames();
125→    expect(names.some((n) => n.includes(testFileName))).toBe(true);
126→
127→    // Verify footer count is visible and shows a number
128→    const countText = await searchPalette.getFooterCountText();
129→    expect(countText).toMatch(/\d+ result/);
130→
131→    // Close
132→    await page.keyboard.press('Escape');
133→    await searchPalette.waitForClosed({ timeout: 5000 });
134→  });
135→
136→  test('2.2 No results for nonsense query', async () => {
137→    // Open palette
138→    await page.keyboard.press('Meta+k');
139→    await searchPalette.waitForOpen({ timeout: 5000 });
140→
141→    // Type nonsense query
142→    await searchPalette.typeQuery('zzzzxqwnofile999');
143→
144→    // Wait for debounce (150ms) + rendering
145→    await page.waitForTimeout(500);
146→
147→    // Verify no results
148→    const resultCount = await searchPalette.getResultCount();
149→    expect(resultCount).toBe(0);
150→
151→    // Verify "no results" message is visible
152→    await expect(searchPalette.noResults()).toBeVisible();
153→
154→    // Close
155→    await page.keyboard.press('Escape');
156→    await searchPalette.waitForClosed({ timeout: 5000 });
157→  });
158→
159→  // ============================================
160→  // 3. Navigation from search results
161→  // ============================================
162→
163→  test('3.1 Select result and verify navigation', async () => {
164→    // Open palette
165→    await page.keyboard.press('Meta+k');
166→    await searchPalette.waitForOpen({ timeout: 5000 });
167→
168→    // Type query matching the test file
169→    await searchPalette.typeQuery(`search-test-${runId}`);
170→    await searchPalette.waitForResults({ timeout: 15000 });
171→
172→    // Click the first result
173→    await searchPalette.clickResult(0);
174→
175→    // Verify palette closes
176→    await searchPalette.waitForClosed({ timeout: 5000 });
177→
178→    // Verify URL is on /files (root folder, since file was uploaded to root)
179→    await page.waitForURL('**/files**', { timeout: 10000 });
180→
181→    // Verify the file is visible in the file list (navigation landed correctly)
182→    await expect(fileList.getItem(testFileName)).toBeVisible({ timeout: 10000 });
183→  });
184→
185→  test('3.2 Keyboard navigation with Enter selects result', async () => {
186→    // Open palette
187→    await page.keyboard.press('Meta+k');
188→    await searchPalette.waitForOpen({ timeout: 5000 });
189→
190→    // Type query matching the test file
191→    await searchPalette.typeQuery(`search-test-${runId}`);
192→    await searchPalette.waitForResults({ timeout: 15000 });
193→
194→    // First result should be auto-selected (index 0)
195→    // Press Enter to select it
196→    await page.keyboard.press('Enter');
197→
198→    // Verify palette closes
199→    await searchPalette.waitForClosed({ timeout: 5000 });
200→
201→    // Verify URL is on /files
202→    await page.waitForURL('**/files**', { timeout: 10000 });
203→  });
204→
205→  // ============================================
206→  // 4. Dismissal behaviors
207→  // ============================================
208→
209→  test('4.1 Escape closes palette', async () => {
210→    // Open palette
211→    await page.keyboard.press('Meta+k');
212→    await searchPalette.waitForOpen({ timeout: 5000 });
213→
214→    // Type some text
215→    await searchPalette.typeQuery('some-text');
216→
217→    // Press Escape
218→    await page.keyboard.press('Escape');
219→
220→    // Verify palette closes
221→    await searchPalette.waitForClosed({ timeout: 5000 });
222→  });
223→
224→  test('4.2 Click outside closes palette', async () => {
225→    // Open palette
226→    await page.keyboard.press('Meta+k');
227→    await searchPalette.waitForOpen({ timeout: 5000 });
228→
229→    // Click the backdrop (near top-left corner, outside the centered palette)
230→    await searchPalette.backdrop().click({ position: { x: 10, y: 10 } });
231→
232→    // Verify palette closes
233→    await searchPalette.waitForClosed({ timeout: 5000 });
234→  });
235→
236→  // ============================================
237→  // 9. Cleanup
238→  // ============================================
239→
240→  test('9.1 Cleanup', async () => {
241→    // Delete the test file from CipherBox
242→    // Right-click the test file and delete it
243→    const isVisible = await fileList.isItemVisible(testFileName);
244→    if (isVisible) {
245→      await fileList.rightClickItem(testFileName);
246→      const deleteOption = page.locator('.context-menu-item', { hasText: 'Delete' });
247→      if (await deleteOption.isVisible({ timeout: 2000 }).catch(() => false)) {
248→        await deleteOption.click();
249→        // Confirm deletion if dialog appears
250→        const confirmBtn = page.locator('.dialog-button--destructive');
251→        if (await confirmBtn.isVisible({ timeout: 2000 }).catch(() => false)) {
252→          await confirmBtn.click();
253→        }
254→        // Wait for item to disappear
255→        await fileList.waitForItemToDisappear(testFileName, { timeout: 15000 }).catch(() => {
256→          // File may already be gone
257→        });
258→      }
259→    }
260→
261→    // Cleanup local test files
262→    cleanupTestFiles();
263→  });
264→});
