/* ==========================================================================
   Search Palette - Command Palette Overlay
   Terminal aesthetic: JetBrains Mono, green on black, sharp corners
   ========================================================================== */

/* Backdrop */
.search-backdrop {
  position: fixed;
  inset: 0;
  background: rgb(0 0 0 / 80%);
  z-index: 100;
  display: flex;
  justify-content: center;
  padding-top: 120px;
}

/* Palette container */
.search-palette {
  width: 600px;
  max-height: calc(100vh - 200px);
  background: var(--color-black);
  border: 1px solid var(--color-green-primary);
  border-radius: 0;
  display: flex;
  flex-direction: column;
  font-family: var(--font-family-mono);
  overflow: hidden;
  align-self: flex-start;
}

/* Search input row */
.search-input-row {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--color-border-dim);
  gap: 8px;
}

.search-icon {
  color: var(--color-text-secondary);
  font-size: 14px;
  flex-shrink: 0;
}

.search-input {
  flex: 1;
  background: none;
  border: none;
  color: var(--color-text-primary);
  font-family: var(--font-family-mono);
  font-size: 14px;
  outline: none;
  caret-color: var(--color-green-primary);
}

.search-input::placeholder {
  color: var(--color-text-dim);
}

.search-input:focus-visible {
  outline: none;
}

.search-esc-hint {
  color: var(--color-text-dim);
  font-size: 10px;
  border: 1px solid var(--color-text-dim);
  padding: 1px 4px;
  flex-shrink: 0;
}

/* Results */
.search-results {
  flex: 1;
  overflow-y: auto;
  max-height: 400px;
}

.search-result-item {
  display: flex;
  align-items: center;
  padding: 8px 16px;
  cursor: pointer;
  gap: 10px;
  border-left: 2px solid transparent;
}

.search-result-item:hover,
.search-result-item.selected {
  background: var(--color-nav-active);
  border-left-color: var(--color-green-primary);
}

.search-result-icon {
  color: var(--color-text-secondary);
  font-size: 14px;
  flex-shrink: 0;
  width: 20px;
  text-align: center;
}

.search-result-item.selected .search-result-icon,
.search-result-icon.icon-bright {
  color: var(--color-green-primary);
}

.search-result-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.search-result-name {
  color: var(--color-text-primary);
  font-size: 12px;
  font-weight: var(--font-weight-bold);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.search-result-name mark {
  background: none;
  color: var(--color-green-primary);
  text-decoration: underline;
}

.search-result-path {
  color: var(--color-text-dim);
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.search-result-date {
  color: var(--color-text-dim);
  font-size: 10px;
  flex-shrink: 0;
  text-align: right;
}

/* Empty/building states */
.search-building,
.search-no-results {
  padding: 24px 16px;
  color: var(--color-text-dim);
  font-size: 12px;
  text-align: center;
}

/* Footer */
.search-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  border-top: 1px solid var(--color-border-dim);
}

.search-footer-hints {
  color: var(--color-text-dim);
  font-size: 10px;
}

.search-footer-hints kbd {
  display: inline;
  font-family: var(--font-family-mono);
  font-size: 10px;
  color: var(--color-text-secondary);
}

.search-footer-count {
  color: var(--color-text-dim);
  font-size: 10px;
}

/* ==========================================================================
   Responsive
   ========================================================================== */

@media (max-width: 768px) {
  .search-palette {
    width: calc(100vw - 32px);
  }

  .search-backdrop {
    padding-top: 80px;
  }
}

